          if (!ws.length) ws = [{ id: "local", title: "本地看板", path: "" }];
          if (cancelled) return;
          const saved = lsGet("dsh.task-board.ws");
          const cur = ws.some((w) => w.id === saved) ? saved : ws[0].id;
          setWsList(ws);
          const b = await loadBoard(cur);
