        const b = boardStateRef.current;
        if (!b || !wsIdRef.current) return;
        if (!dirtyRef.current) { setSaveState("ok"); return; }
        const editAt = editSeqRef.current;
        const forWs = wsIdRef.current;
        const rev = serverRevRef.current;
